def slug(s): return re.sub(r'[^a-z0-9]+', '-', s.lower()).strip('-')

out = []
for e in EVENTS:
    for i, r in enumerate(e["recs"]):
        finish, tech, baits, cover, section, summary, extra = r
        c = dict(e["c"])
        for k in ("sky", "wind", "water_color", "level_trend", "front"):
            if k in extra: c[k] = extra[k]
        out.append({
            "id": f"{e['key']}-{finish if finish else 'x' + str(i)}",
            "date": e["date"], "event": e["event"], "finish": finish,
            "water_temp_f": extra.get("temp"), "conditions": c,
            "season_phase": e["phase"], "technique": tech, "baits": baits,
            "cover_structure": cover, "section": section, "summary": summary,
            "source_url": extra.get("url", e["url"]),
        })
json.dump(out, open("data/patterns.json", "w"), indent=1)
print(len(EVENTS), "events,", len(out), "records")
